import{z as i,x as d,o as E,c as p,q as n,j as A,D as t,d as e,s as l,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"结构冒险","description":"","frontmatter":{"title":"结构冒险","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/structural-hazard.md","filePath":"cs/structural-hazard.md","lastUpdated":1791413859000}'),B={name:"cs/structural-hazard.md"};function m(c,a,D,h,u,C){const s=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="结构冒险" tabindex="-1">结构冒险 <a class="header-anchor" href="#结构冒险" aria-label="Permalink to &quot;结构冒险&quot;">​</a></h1><div class="epigraph"><p>流水线假定每一级在同一拍都能得到它要的硬件；两级抢同一端口，重叠就退回停顿。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/pipeline-registers">上一课</a>把 RISC-V 整数通路切成 IF/ID/EX/MEM/WB，并假定指令存储器与数据存储器可以同时访问。本课不重讲五级划分。缺口是：真实硅上端口、ALU 和写回通路都是有限份，两级在同一拍要同一份，重叠无法发生。本课只命名结构冒险，并指出用复制资源或停顿来消掉它。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若指令和数据共用一个存储器端口，IF 取指与 MEM 访存会在同一拍冲突。若寄存器堆只有一个写口，而设计又想在 ID 读、WB 写之外再塞一条写，也会撞。缺口不是数据相关——操作数可以已经准备好——而是<strong>功能单元的个数不够同时服务流水线里的那几条指令</strong>。</p><p><span class="marginnote">结构冒险翻译成白话：不是「数还没算出来」（那是数据冒险），而是「机房不够用」——流水线第 1 级和第 4 级在同一拍都要进同一间机房，机房只有一间，只能有一级等下一拍。</span></p><p>单周期从来不会有这个问题：一拍里只有一条指令占用全部硬件。重叠一旦开始，资源日历必须按级排。本课不处理寄存器值尚未产生的情况，那是<a href="/cs/data-hazard-forward">数据冒险与转发</a>。</p><p><span class="marginnote">Hennessy/Patterson 把冒险分成结构、数据、控制三类。结构是资源日历，不是值依赖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先列出每级每拍要占用的端口：IF 读指令、ID 读寄存器、EX 用 ALU、MEM 读或写数据、WB 写寄存器。若某拍两级指向同一不可共享资源，插入气泡：后来的指令在前一级停住，冲突级空转一拍。</p><p><span class="marginnote">数字实例：理想流水线每拍出一条结果，CPI 为 1；若每 10 条指令撞上 1 次结构冲突、每次停 1 拍，CPI 变成 1.1——性能直接少一成。这就是「复制端口换面积」与「停顿换时间」讨价还价的账本。</span></p><p>另一条路是复制：哈佛结构把指令与数据分开；寄存器堆做成两读一写，正好匹配 ID 与 WB。经典五级教学机靠这两份复制，把结构冒险从整数核里拿掉，后面才好单独讲数据相关。</p>',12)),(E(),A(o,null,{default:t(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22IF%20%E5%8F%96%E6%8C%87%22%5D%20--%3E%20MEM%5B%22MEM%20%E8%AE%BF%E5%AD%98%22%5D%0A%20%20IF%20--%3E%20STALL%5B%22%E5%85%B1%E4%BA%AB%E7%AB%AF%E5%8F%A3%EF%BC%9A%E5%81%9C%E9%A1%BF%22%5D%0A%20%20MEM%20--%3E%20STALL%0A%20%20IF%20--%3E%20SPLIT%5B%22%E5%88%86%E4%BD%93%E5%AD%98%E5%82%A8%EF%BC%9A%E5%8F%AF%E9%87%8D%E5%8F%A0%22%5D%0A%20%20MEM%20--%3E%20SPLIT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("停顿把理想 CPI 从 1 抬高：每发生一次结构冲突，吞吐少一条。复制把面积和布线换成冲突消失。设计选择是定量的：端口少、停顿多，还是端口多、面积大。"),r("a",{href:"/cs/cpi-amdahl"},"CPI 与阿姆达尔"),e("会把这类损失写进公式；本课只承认损失来自资源不够。")],-1)),a[5]||(a[5]=r("p",null,"写回与译码可以安排在寄存器堆的不同相：前半拍写、后半拍读，让同一拍内 WB 的结果对 ID 可见。这是时序技巧，不是转发；转发处理的是更早还在 ALU 里的值。",-1)),(E(),A(o,null,{default:t(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK%5B%22%E4%B8%80%E4%B8%AA%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20H1%5B%22%E5%89%8D%E5%8D%8A%E6%8B%8D%EF%BC%9AWB%20%E7%BA%A7%E5%86%99%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20CLK%20--%3E%20H2%5B%22%E5%90%8E%E5%8D%8A%E6%8B%8D%EF%BC%9AID%20%E7%BA%A7%E8%AF%BB%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%22%5D%0A%20%20H1%20--%3E%20SHARE%5B%22%E5%90%8C%E4%B8%80%E7%BB%84%E7%AB%AF%E5%8F%A3%E8%A2%AB%E9%94%99%E5%B3%B0%E5%85%B1%E7%94%A8%22%5D%0A%20%20H2%20--%3E%20SHARE%0A%20%20SHARE%20--%3E%20NOCOPY%5B%22%E4%B8%8D%E5%A4%8D%E5%88%B6%E7%AB%AF%E5%8F%A3%EF%BC%8C%E8%BF%99%E5%A4%84%E7%BB%93%E6%9E%84%E5%86%92%E9%99%A9%E5%B0%B1%E5%9C%B0%E6%B6%88%E6%8E%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：把「前半拍写、后半拍读」当成转发。转发解决的是「值还在 ALU 里没写回」，靠旁路把值直接递给下一级；半拍错峰解决的是「同一端口一拍被两级抢」，值早已写进寄存器堆——两者消的是不同的险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cache：存储器端口暂时仍是理想的组合阵列。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>已经说明 DRAM 做不到每拍随机访问，那是局部性课才接上的缺口。也不处理多发射：超标量会让结构冒险重新变严重，因为每拍要更多端口。</p><p>后课默认：经典五级整数核已用分体存储和两读一写堆消掉结构冒险；再谈到停顿，先怀疑数据或控制相关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构冒险是同一拍两级抢同一份硬件，不是值没算完。</li><li>消法是复制端口，或插入气泡。</li><li>数据相关与分支是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>Computer Architecture: A Quantitative Approach</em>。</li></ul>',6))])}const I=i(B,[["render",m]]);export{f as __pageData,I as default};
